import{_ as n,o as l,c as a,a0 as e}from"./chunks/framework.DhQjJcnt.js";const g=JSON.parse('{"title":"Skill: /grill","description":"","frontmatter":{},"headers":[],"relativePath":"references/skills/grill.md","filePath":"references/skills/grill.md"}'),t={name:"references/skills/grill.md"};function o(r,i,c,s,h,u){return l(),a("div",null,[...i[0]||(i[0]=[e('<h1 id="skill-grill" tabindex="-1">Skill: <code>/grill</code> <a class="header-anchor" href="#skill-grill" aria-label="Permalink to &quot;Skill: `/grill`&quot;">​</a></h1><h2 id="ten" tabindex="-1">Tên <a class="header-anchor" href="#ten" aria-label="Permalink to &quot;Tên&quot;">​</a></h2><p><code>grill</code></p><h2 id="cach-dung-command-trigger" tabindex="-1">Cách dùng (Command/Trigger) <a class="header-anchor" href="#cach-dung-command-trigger" aria-label="Permalink to &quot;Cách dùng (Command/Trigger)&quot;">​</a></h2><ul><li>Gọi qua slash command: <code>/grill</code></li><li>Có thể truyền tham số về Layer cần chất vấn ở phía sau (VD: <code>/grill module</code>, <code>/grill overview</code>).</li></ul><h2 id="input-du-lieu-đau-vao" tabindex="-1">Input (Dữ liệu đầu vào) <a class="header-anchor" href="#input-du-lieu-đau-vao" aria-label="Permalink to &quot;Input (Dữ liệu đầu vào)&quot;">​</a></h2><ul><li>Đọc tài liệu ở lớp (Layer) đang cần phân tích.</li><li>Xác định Layer mục tiêu (Ví dụ: Module, Surface, Overview, Journey, Db-ERD).</li></ul><h2 id="output-ket-qua-mong-đoi" tabindex="-1">Output (Kết quả mong đợi) <a class="header-anchor" href="#output-ket-qua-mong-đoi" aria-label="Permalink to &quot;Output (Kết quả mong đợi)&quot;">​</a></h2><ul><li>Đây là một <strong>Bộ điều hướng Chất vấn (Discovery Router)</strong>.</li><li>KHÔNG tự tiện ghi đè (Overwrite) file Spec hay Kiến trúc khi chưa chốt hạ vấn đề.</li><li>Đưa ra chuỗi các câu hỏi sắc bén (AskQuestion Form) hiển thị trực tiếp trên Chat Thread để người dùng (Member) trả lời.</li><li>Sau khi chốt xong, nó sẽ chuyển giao (Handoff) cho các lệnh sinh tài liệu tương ứng (VD: <code>/module</code>, <code>/surfaces</code>).</li></ul><h2 id="description-y-nghia" tabindex="-1">Description / Ý nghĩa <a class="header-anchor" href="#description-y-nghia" aria-label="Permalink to &quot;Description / Ý nghĩa&quot;">​</a></h2><ul><li>Đóng vai trò là &quot;Cổng gác&quot; (Hard Confirmation Gate).</li><li>Dùng trong trường hợp: Thông tin yêu cầu ban đầu quá sơ sài, thiếu hụt, hoặc bạn không chắc chắn về thiết kế ở bước tiếp theo.</li><li>Trình tự đặt câu hỏi (Question Order) ưu tiên: <ol><li>Phạm vi và Mục tiêu.</li><li>Người dùng (Actors) và Kênh (Channels).</li><li>Ranh giới và Quyền sở hữu (Ownership).</li><li>Luồng chuẩn (Happy path).</li><li>Luồng ngoại lệ và lỗi (Exceptions &amp; edge cases).</li><li>Phạm vi dùng chung (Common scope).</li><li>Định dạng đầu ra.</li></ol></li><li><strong>ĐẠO LUẬT THÉP (SSOT_AGENT_PROTOCOL):</strong><ul><li><strong>TUYỆT ĐỐI KHÔNG</strong> được bịa ra thông tin nghiệp vụ (invent business data) để lấp liếm sự thiếu hụt.</li><li>Phải để nguyên thẻ <code>#missing_info</code> hoặc đặt câu hỏi.</li><li>Form AskQuestion <strong>BẮT BUỘC</strong> phải có tuỳ chọn &quot;Log as Tech Debt (Pending)&quot;. Nếu người dùng chọn cái này, thông tin sẽ bị ném vào <code>qa-inbox.md</code> thay vì làm đình trệ công việc.</li></ul></li></ul><h2 id="cac-skill-lien-quan" tabindex="-1">Các Skill liên quan <a class="header-anchor" href="#cac-skill-lien-quan" aria-label="Permalink to &quot;Các Skill liên quan&quot;">​</a></h2><ul><li>Router trung tâm cho hàng loạt skill chất vấn con: <code>/grill-bqa</code>, <code>/grill-dev</code>, <code>/grill-docs</code>.</li></ul><hr><h2 id="example-prompt-mau-goi" tabindex="-1">Example prompt (mẫu gọi) <a class="header-anchor" href="#example-prompt-mau-goi" aria-label="Permalink to &quot;Example prompt (mẫu gọi)&quot;">​</a></h2><p><strong>Quy tắc:</strong> một session = một command · chat mới khi đổi phase · cập nhật <code>.harness/progress.md</code> nếu có.</p><p><strong>Khi nào:</strong> Gọi khi scope khớp mô tả skill ở trên.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/grill</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>Surface: {admin-web} · Module: {CMP-…} · Scope: {mô tả ngắn}</span></span></code></pre></div>',18)])])}const p=n(t,[["render",o]]);export{g as __pageData,p as default};
